const metrics = $json;
const callbackHitRate = metrics.inboundLeads ? Math.round((metrics.callbacksUnder45s / metrics.inboundLeads) * 100) : 0;
const conversionRate = metrics.discoveryScheduled ? Math.round((metrics.dealsClosedWon / metrics.discoveryScheduled) * 100) : 0;
const digest = `Postal Presort Weekly Digest
Period: ${metrics.period}

Inbound leads: ${metrics.inboundLeads}
Callbacks under 45s: ${metrics.callbacksUnder45s} (${callbackHitRate}%)
Discovery calls scheduled: ${metrics.discoveryScheduled}
Deals closed won: ${metrics.dealsClosedWon} (${conversionRate}% of discovery)

Stale deals (>14d): ${metrics.staleDeals}
Review opportunities: ${metrics.reviewOpportunities}
Reviews requested: ${metrics.reviewsRequested}
Workflow failures: ${metrics.workflowFailures}`;
return [{ json: { ...metrics, callbackHitRate, conversionRate, digest } }];
